import { Ionicons } from "@expo/vector-icons";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useRouter } from "expo-router";
import { useState } from "react";
import { ActivityIndicator, Pressable, StyleSheet, Text, TextInput, View } from "react-native";
import { ModuleCard } from "../../ui/ModuleCard";
import { Screen } from "../../ui/Screen";
import { colors, radius, spacing } from "../../ui/tokens";
import { firebaseAuth } from "../auth/firebase";
import { createVendorVoucher, getVendorVouchers } from "./vendor.api";

const tools = [["/vendor/engagement", "Reviews and Q&A", "Read customer feedback and answer product questions", "star-outline"], ["/vendor/category-requests", "Category access", "Request approval for additional product categories", "git-pull-request-outline"], ["/vendor/messages", "Customer messages", "Continue marketplace conversations", "chatbubbles-outline"]] as const;

export function VendorMarketingScreen() {
  const router = useRouter();
  const user = firebaseAuth?.currentUser ?? null;
  const cache = useQueryClient();
  const vouchers = useQuery({ queryKey: ["vendor", "vouchers"], queryFn: () => getVendorVouchers(user!), enabled: Boolean(user) });
  const [form, setForm] = useState({ code: "", type: "PERCENT" as "PERCENT" | "FIXED", value: "10", days: "30" });
  const create = useMutation({ mutationFn: () => { const startsAt = new Date(); const days = Math.max(1, Number(form.days) || 30); return createVendorVoucher(user!, { code: form.code, discountType: form.type, value: Number(form.value), startsAt: startsAt.toISOString(), endsAt: new Date(startsAt.getTime() + days * 86_400_000).toISOString() }); }, onSuccess: async () => { setForm({ code: "", type: "PERCENT", value: "10", days: "30" }); await cache.invalidateQueries({ queryKey: ["vendor", "vouchers"] }); } });
  const active = vouchers.data?.filter((item) => item.active && new Date(item.endsAt) > new Date()).length ?? 0;
  return <Screen eyebrow="SELLER GROWTH" title="Marketing center" description="Create seller-funded offers and manage customer engagement from one workspace.">
    <View style={styles.hero}><View style={styles.heroIcon}><Ionicons color={colors.surface} name="megaphone" size={28} /></View><View style={styles.flex}><Text style={styles.heroTitle}>Grow your store</Text><Text style={styles.heroMeta}>{active} active voucher{active === 1 ? "" : "s"} · {vouchers.data?.length ?? 0} total campaigns</Text></View></View>
    <View style={styles.tools}>{tools.map(([href, title, copy, icon]) => <Pressable key={href} onPress={() => router.push(href)} style={styles.tool}><View style={styles.toolIcon}><Ionicons color={colors.primary} name={icon} size={22} /></View><View style={styles.flex}><Text style={styles.toolTitle}>{title}</Text><Text style={styles.toolMeta}>{copy}</Text></View><Ionicons color={colors.muted} name="chevron-forward" size={18} /></Pressable>)}</View>
    <ModuleCard title="Create a voucher" meta="Offer a percentage or fixed-value discount for a limited period."><View style={styles.row}><Field label="Voucher code" onChangeText={(code) => setForm({ ...form, code: code.toUpperCase().replace(/[^A-Z0-9]/g, "") })} placeholder="SAVE10" value={form.code} /><Field keyboardType="numeric" label="Discount value" onChangeText={(value) => setForm({ ...form, value })} placeholder="10" value={form.value} /><Field keyboardType="numeric" label="Valid days" onChangeText={(days) => setForm({ ...form, days })} placeholder="30" value={form.days} /></View><Text style={styles.label}>Discount type</Text><View style={styles.types}>{(["PERCENT", "FIXED"] as const).map((type) => <Pressable key={type} onPress={() => setForm({ ...form, type })} style={[styles.type, form.type === type && styles.typeActive]}><Text style={[styles.typeText, form.type === type && styles.typeTextActive]}>{type === "PERCENT" ? "Percentage (%)" : "Fixed amount (৳)"}</Text></Pressable>)}</View><Pressable disabled={create.isPending || form.code.length < 3 || Number(form.value) <= 0} onPress={() => create.mutate()} style={[styles.primary, (create.isPending || form.code.length < 3 || Number(form.value) <= 0) && styles.disabled]}>{create.isPending ? <ActivityIndicator color={colors.surface} /> : <Text style={styles.primaryText}>Create voucher</Text>}</Pressable>{create.error ? <Text style={styles.error}>{create.error.message}</Text> : null}</ModuleCard>
    <Text style={styles.heading}>Your vouchers</Text>{vouchers.isLoading ? <ActivityIndicator color={colors.primary} /> : null}<View style={styles.vouchers}>{vouchers.data?.map((item) => <View key={item.id} style={styles.voucher}><View style={styles.ticket}><Ionicons color={colors.accent} name="ticket-outline" size={23} /></View><View style={styles.flex}><Text style={styles.code}>{item.code}</Text><Text style={styles.toolMeta}>{new Date(item.startsAt).toLocaleDateString("en-BD")} – {new Date(item.endsAt).toLocaleDateString("en-BD")}</Text></View><Text style={[styles.state, !item.active && styles.inactive]}>{item.active ? "ACTIVE" : "INACTIVE"}</Text></View>)}</View>{!vouchers.isLoading && !vouchers.data?.length ? <View style={styles.empty}><Text style={styles.toolTitle}>No vouchers created yet</Text><Text style={styles.toolMeta}>Create your first seller-funded offer above.</Text></View> : null}
  </Screen>;
}

function Field(props: React.ComponentProps<typeof TextInput> & { label: string }) { const { label, ...input } = props; return <View style={styles.field}><Text style={styles.label}>{label}</Text><TextInput placeholderTextColor={colors.muted} style={styles.input} {...input} /></View>; }
const styles = StyleSheet.create({ flex: { flex: 1 }, hero: { alignItems: "center", backgroundColor: colors.navy, borderRadius: radius.xl, flexDirection: "row", gap: spacing.md, padding: spacing.xl }, heroIcon: { alignItems: "center", backgroundColor: colors.accent, borderRadius: radius.lg, height: 56, justifyContent: "center", width: 56 }, heroTitle: { color: colors.surface, fontSize: 22, fontWeight: "700" }, heroMeta: { color: "#cbd5e1", marginTop: 4 }, tools: { flexDirection: "row", flexWrap: "wrap", gap: spacing.md }, tool: { alignItems: "center", backgroundColor: colors.surface, borderColor: colors.border, borderRadius: radius.lg, borderWidth: 1, flex: 1, flexDirection: "row", gap: spacing.sm, minWidth: 280, padding: spacing.md }, toolIcon: { alignItems: "center", backgroundColor: colors.primarySoft, borderRadius: radius.md, height: 44, justifyContent: "center", width: 44 }, toolTitle: { color: colors.text, fontWeight: "700" }, toolMeta: { color: colors.muted, fontSize: 10, lineHeight: 16, marginTop: 3 }, row: { flexDirection: "row", flexWrap: "wrap", gap: spacing.md }, field: { flex: 1, gap: 6, minWidth: 180 }, label: { color: colors.text, fontSize: 11, fontWeight: "700" }, input: { backgroundColor: "#f8fafc", borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, color: colors.text, minHeight: 46, paddingHorizontal: 12 }, types: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, type: { borderColor: colors.border, borderRadius: radius.pill, borderWidth: 1, paddingHorizontal: 13, paddingVertical: 9 }, typeActive: { backgroundColor: colors.primary, borderColor: colors.primary }, typeText: { color: colors.muted, fontSize: 10, fontWeight: "700" }, typeTextActive: { color: colors.surface }, primary: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, justifyContent: "center", minHeight: 48 }, primaryText: { color: colors.surface, fontWeight: "700" }, disabled: { opacity: .45 }, heading: { color: colors.text, fontSize: 20, fontWeight: "700" }, vouchers: { gap: spacing.sm }, voucher: { alignItems: "center", backgroundColor: colors.surface, borderColor: colors.border, borderRadius: radius.lg, borderWidth: 1, flexDirection: "row", gap: spacing.md, padding: spacing.md }, ticket: { alignItems: "center", backgroundColor: colors.accentSoft, borderRadius: radius.md, height: 44, justifyContent: "center", width: 44 }, code: { color: colors.text, fontSize: 16, fontWeight: "700", letterSpacing: 1 }, state: { backgroundColor: "#dcfce7", borderRadius: radius.pill, color: colors.success, fontSize: 8, fontWeight: "700", overflow: "hidden", paddingHorizontal: 9, paddingVertical: 6 }, inactive: { backgroundColor: "#f1f5f9", color: colors.muted }, empty: { alignItems: "center", borderColor: colors.border, borderRadius: radius.lg, borderStyle: "dashed", borderWidth: 1, gap: 5, padding: spacing.xl }, error: { color: colors.danger } });
